import {observe} from '@github/selector-observer'
import {onKey} from '@github-ui/onfocus'

onKey('keyup', '.js-user-code-field', event => {
  const currentTarget = event.currentTarget as HTMLElement
  if (!currentTarget) return

  const alphaNumericRegExp = new RegExp('^(Digit[0-9]|Key[A-Z]|Numpad[0-9])')

  let inputElement

  switch (true) {
    case event.code === 'Backspace': {
      const previousField = currentTarget.getAttribute('data-previous')
      inputElement = document.querySelector(`#${previousField}`) as HTMLInputElement

      break
    }
    case alphaNumericRegExp.test(event.code): {
      const nextField = currentTarget.getAttribute('data-next')
      inputElement = document.querySelector(`#${nextField}`) as HTMLInputElement

      break
    }
  }

  inputElement?.focus()
})

// Replace all of the input fields if data from the
// clipboard matches the user code pattern.
observe('.js-user-code-field', {
  constructor: HTMLInputElement,
  add(el) {
    el.addEventListener('paste', (event: Event) => {
      event.preventDefault()

      const clipboardEvent = event as ClipboardEvent

      const {clipboardData} = clipboardEvent
      if (!clipboardData) return

      const userCode = clipboardData.getData('text')

      // User code looks like A1B2-3CD4
      const userCodeRegExp = new RegExp(/^[a-zA-Z|\d]{4}-[a-zA-Z|\d]{4}$/)
      if (!userCodeRegExp.test(userCode)) return

      let lastInputElement

      for (const inputField of document.querySelectorAll<HTMLInputElement>('input.js-user-code-field')) {
        if (inputField.readOnly) continue
        lastInputElement = inputField

        // An example ID would be user-code-0
        const index = Number(inputField.id.slice(-1))
        inputField.value = userCode[index]!
      }

      lastInputElement?.focus()
    })
  },
})
